def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            y0, y1 = min(y for y,x in cells), max(y for y,x in cells)
            x0, x1 = min(x for y,x in cells), max(x for y,x in cells)
            objs.append((color, [(y-y0,x-x0) for y,x in cells],
                         y1-y0+1, x1-x0+1, y0, x0))

    # Rearrange the component figures into upper and lower rows, preserving
    # their horizontal positions and placing each row against its edge.
    out = [[0]*w for _ in range(h)]
    for color, cells, oh, ow, y, x in objs:
        top = y < h//2
        if color == 2:
            top = False
        elif color == 8:
            top = True
        elif color == 3:
